const PEGADINHAS_B1 = [
  {t:"Hoy he comido, ayer comí", r:"Na Espanha, o que aconteceu num tempo <b>ainda aberto</b> (hoy, esta semana, este año, alguna vez) vai no <b>perfecto</b> (he comido). Num tempo <b>fechado</b> (ayer, el año pasado, en 2019), vai no <b>indefinido</b> (comí). Em português usamos o mesmo passado para os dois.",
   ex:[["Hoy he desayunado churros.","Hoje tomei churros no café da manhã."],["Ayer desayuné en el hotel.","Ontem tomei café no hotel."],["Esta semana he caminado mucho.","Esta semana andei muito."],["El año pasado estuve en Lisboa.","No ano passado estive em Lisboa."]], bad:"'Ayer he ido a Toledo' soa estranho na Espanha; 'ayer fui'."},
  {t:"Era ou fue: cenário ou fato", r:"<b>Imperfecto</b> (era, había, hacía) descreve o cenário e os hábitos. <b>Indefinido</b> (fue, hubo, hizo) conta o que aconteceu. <i>Hacía frío (cenário) y de repente empezó a nevar (fato).</i>",
   ex:[["Cuando llegamos, llovía.","Quando chegamos, chovia."],["De repente empezó a llover.","De repente começou a chover."],["Antes vivía en el centro.","Antes morava no centro."],["El año pasado me mudé.","No ano passado me mudei."]], bad:"'Cuando llegamos, llovió' muda o sentido: a chuva começou na hora."},
  {t:"Hablo ou habló: o acento é o tempo", r:"Sem acento, <b>hablo</b> = eu falo (agora). Com acento, <b>habló</b> = ele falou (ontem). O mesmo com compro/compró, llego/llegó, pago/pagó. Na fala, a sílaba forte muda de lugar.",
   ex:[["Pago con tarjeta.","Pago com cartão."],["Pagó con tarjeta.","Ele pagou com cartão."],["Llego a las ocho.","Chego às oito."],["Llegó a las ocho.","Ele chegou às oito."]], bad:"Dizer 'pago' querendo dizer 'pagou': o garçom acha que você vai pagar agora."},
  {t:"Quiero que vengas, não 'que vienes'", r:"Depois de <b>quiero que, espero que, recomiendo que, es mejor que, ojalá</b>, o verbo vai no <b>subjuntivo</b>: vengas, tengas, sea, haya. É a parte mais nova para quem fala português, porque nós usamos 'venha' cada vez menos.",
   ex:[["Quiero que vengas.","Quero que você venha."],["Espero que te guste.","Espero que você goste."],["Es mejor que vayas en tren.","É melhor que você vá de trem."],["Ojalá haga sol.","Tomara que faça sol."]], bad:"'Espero que te gusta' e 'quiero que vienes' são os erros mais comuns do nível."},
  {t:"Quiero ir, não 'quiero que yo vaya'", r:"Se quem quer e quem faz são a <b>mesma pessoa</b>, use o <b>infinitivo</b>: <i>Quiero ir. Espero volver. Prefiero quedarme.</i> O subjuntivo só entra quando o sujeito muda.",
   ex:[["Quiero ir al Albaicín.","Quero ir ao Albaicín."],["Quiero que vayamos juntos.","Quero que vamos juntos."],["Espero volver pronto.","Espero voltar logo."],["Espero que vuelvas pronto.","Espero que você volte logo."]], bad:"'Quiero que yo vaya' não existe."},
  {t:"Cuando llegue, não 'cuando llegaré'", r:"Falando do futuro, depois de <b>cuando, en cuanto, hasta que, antes de que</b> vai o <b>subjuntivo</b>, nunca o futuro: <i>Cuando <b>llegue</b>, te llamo.</i> Em português dizemos 'quando chegar', que é o futuro do subjuntivo; em espanhol se usa o presente do subjuntivo.",
   ex:[["Cuando llegues, avísame.","Quando você chegar, me avise."],["Te llamo en cuanto salga.","Te ligo assim que sair."],["Esperamos hasta que abran.","Esperamos até que abram."],["Antes de que cierren, compra el pan.","Antes que fechem, compre o pão."]], bad:"'Cuando llegaré te llamo' é calco do português 'quando chegarei'."},
  {t:"Si llueve, não 'si llueva'", r:"Condição real: <b>si + presente do indicativo</b>: <i>Si llueve, vamos al museo.</i> Nunca subjuntivo nem futuro depois de <i>si</i> nesse caso. Já o 'se chover' português é futuro do subjuntivo, que em espanhol vira presente simples.",
   ex:[["Si hace sol, iremos a la playa.","Se fizer sol, iremos à praia."],["Si tienes tiempo, llámame.","Se tiver tempo, me liga."],["Si no hay entradas, volvemos mañana.","Se não tiver ingressos, voltamos amanhã."]], bad:"'Si hará sol' e 'si haga sol' não existem."},
  {t:"Me duele, não 'yo duelo'", r:"<b>Doler</b> funciona como <i>gustar</i>: a parte do corpo é o sujeito. <i>Me duele la cabeza</i> (singular), <i>me duelen los pies</i> (plural). Com usted: <i>¿Le duele?</i>",
   ex:[["Me duele la garganta.","Minha garganta dói."],["Me duelen las piernas.","Minhas pernas doem."],["¿Le duele al caminar?","Dói ao andar?"],["Ya no me duele.","Já não dói."]], bad:"'Yo duelo la cabeza' não existe."},
  {t:"Llevo tres días con fiebre", r:"Para dizer há quanto tempo algo dura, o espanhol usa <b>llevar</b>: <i>Llevo tres días con fiebre. Llevo dos años aquí. Llevo una hora esperando.</i> Também vale <i>hace tres días que tengo fiebre</i>.",
   ex:[["Llevo dos días sin dormir.","Estou há dois dias sem dormir."],["Llevamos una semana en Madrid.","Estamos há uma semana em Madri."],["¿Cuánto tiempo llevas aquí?","Há quanto tempo você está aqui?"]], bad:"'Tengo fiebre hace tres días' se entende, mas 'llevo tres días con fiebre' é como se diz."},
  {t:"Más que, não 'más de que'", r:"Comparar: <b>más/menos + adjetivo + que</b>: <i>más barato que</i>. <b>Más de</b> só antes de número: <i>más de diez euros</i>. Irregulares: <b>mejor, peor, mayor, menor</b> (não 'más bueno', 'más grande' para idade).",
   ex:[["Este piso es más luminoso que el otro.","Este apartamento é mais claro que o outro."],["Cuesta más de cien euros.","Custa mais de cem euros."],["Mi hermano es mayor que yo.","Meu irmão é mais velho que eu."],["Este vino es mejor.","Este vinho é melhor."]], bad:"'Más grande que yo' para idade: em espanhol é 'mayor que yo'."},
  {t:"Se come a las dos: o 'se' impessoal", r:"Para regras e costumes gerais, o espanhol usa <b>se + verbo</b>: <i>Aquí se cena tarde. ¿Cómo se dice…? Se necesita cita previa.</i> No plural, o verbo concorda: <i>se venden pisos</i>.",
   ex:[["Aquí se come a las dos.","Aqui se almoça às duas."],["¿Dónde se compran los billetes?","Onde se compram as passagens?"],["Se habla español.","Fala-se espanhol."],["No se puede fumar aquí.","Não se pode fumar aqui."]], bad:"'La gente come a las dos' está certo, mas o 'se' é mais natural para o costume geral."},
  {t:"Me dijo que venía, não 'que viene'", r:"Quando o verbo principal está no passado (<i>dijo, preguntó, contó</i>), o presente da fala original vira <b>imperfecto</b>: 'Vengo' → <i>dijo que venía</i>; 'Tengo hora' → <i>preguntó si tenía hora</i>.",
   ex:[["Me dijo que llegaba tarde.","Disse que chegava atrasado."],["Me preguntó si tenía hora.","Perguntou se eu tinha horas."],["Contó que vivía en Granada.","Contou que morava em Granada."]], bad:"'Me dijo que viene' só se o combinado ainda vale e você quer dar ênfase."}
];
